<div class="sale-scroll"><table class="sale-table sale-mobile-table"><thead><tr><th>المنتج</th><th>اللون / المقاس</th><th>الكمية</th><th>سعر الوحدة</th><th>خصم السطر</th><th>نصيبه من خصم الفاتورة</th><th>الصافي</th>@if($showCost ?? false)<th>التكلفة المحفوظة</th>@endif</tr></thead><tbody>@foreach($invoice->items as $item)<tr><td>{{ $item->product_name }}<small>{{ $item->product_code }} — {{ $item->sku }}</small>@if($item->price_reason && ($showCost ?? false))<small>سبب الاستثناء: {{ $item->price_reason }}</small>@endif</td><td data-label="اللون / المقاس">{{ $item->color_name }} / {{ $item->size_name }}</td><td data-label="الكمية">{{ $item->quantity }}@if($item->returned_quantity)<small>المرتجع حاليًا: {{ $item->returned_quantity }}</small>@endif</td>@foreach(['سعر الوحدة'=>$item->unit_price_minor,'خصم السطر'=>$item->line_discount_minor,'خصم الفاتورة المخصص'=>$item->invoice_discount_minor,'الصافي'=>$item->net_minor] as $label=>$amount)<td data-label="{{ $label }}">{{ \App\Support\Sales\Money::format((int)$amount) }} ₪</td>@endforeach @if($showCost ?? false)<td data-label="التكلفة التاريخية">{{ $item->cost_minor === null ? 'غير متاحة — تحتاج مراجعة' : \App\Support\Sales\Money::format((int)$item->cost_minor).' ₪' }}</td>@endif</tr>@endforeach</tbody></table></div>
